package fetvisuals.modules.hud;
import fetvisuals.module.*; import fetvisuals.render.*; import net.minecraft.client.MinecraftClient; import net.minecraft.client.gui.DrawContext; import net.minecraft.client.option.KeyBinding;
public final class Keystrokes extends fetvisuals.module.Module {public Keystrokes(){super("Keystrokes","WASD + mouse buttons",Category.HUD);}public void onHud(DrawContext c,float d){MinecraftClient mc=MinecraftClient.getInstance();int x=8,y=48;String[] k={"W","A","S","D"};for(int i=0;i<4;i++){int xx=i==0?x+34:x+(i-1)*28;int yy=i==0?y:y+28;KeyBinding kb=switch(k[i]){case"W"->mc.options.forwardKey;case"A"->mc.options.leftKey;case"S"->mc.options.backKey;default->mc.options.rightKey;};boolean down=kb.isPressed();RenderUtils.rounded(c,xx,yy,24,24,6,down?0xFFB66DFF:0xF0181422);FontRenderer.draw(c,k[i],xx+8,yy+7,0xFFEAE7F2);}}}
